import {
  MAX_IMPORTED_ASSET_BYTES,
  isAssetTooLarge,
} from "@repo/database/lib/assetLimits";
import type { DGSupabaseClient } from "@repo/database/lib/client";
import { readMirroredAssetUrl, recordMirroredAsset } from "./assetRegistry";

/**
 * Copies one asset out of shared storage and into this graph's own Roam storage.
 *
 * Roam renders an embed by issuing an anonymous cross-origin GET, with no credentials,
 * so whatever an imported page points at has to be fetchable without our auth. Shared
 * storage is private, so the bytes have to land somewhere public: this graph's own
 * Firebase storage, through `file.upload`.
 *
 * Every asset takes this path, whatever platform published it. A Roam-origin asset
 * imported into a second graph is copied too, rather than pointing at the origin graph's
 * URL: recognising a Firebase URL in order to skip the copy would put origin detection
 * back into the destination, and the shortcut would leave this graph's page depending on
 * a blob the origin graph's owner can delete.
 *
 * The copy is irrevocable, and that is deliberate. See design.md Decision 3.
 */

/** The bucket `addFile` writes to, keyed by content hash. */
const SHARED_ASSET_BUCKET = "assets";

export type MirroredAsset = {
  /** The bytes were uploaded to this graph's storage by this call. */
  status: "mirrored";
  contentHash: string;
  url: string;
};

export type ReusedAsset = {
  /** This graph already held a copy, so nothing was uploaded. */
  status: "reused";
  contentHash: string;
  url: string;
};

export type SkippedAsset = {
  status: "skipped";
  contentHash: string;
  reason: "too-large";
  size: number;
  limit: number;
};

export type AssetMirrorResult = MirroredAsset | ReusedAsset | SkippedAsset;

/**
 * The forms `file.upload` resolves to. It returns a block string rather than a URL, and
 * which one depends on the media type, so the URL has to be unwrapped before it can be
 * recorded or written into a link.
 *
 * Anchored, because the input is one upload's return value rather than page content: a
 * pattern that matched loosely would take a URL out of a string this code does not
 * recognise, and recording the wrong URL is worse than reporting an unknown shape.
 */
const UPLOAD_RETURN_PATTERNS = [
  /^!\[[^\]]*\]\((\S+)\)$/, // an image
  /^\{\{\[\[(?:pdf|audio|video)\]\]:\s*(\S+?)\s*\}\}$/, // pdf, audio or video
  /^\{\{(?:pdf|audio|video):\s*(\S+?)\s*\}\}$/, // the same, written without brackets
  /^(https?:\/\/\S+)$/, // everything else, as a bare URL
];

export const extractUploadedUrl = (
  uploadReturn: string,
): string | undefined => {
  const trimmed = uploadReturn.trim();
  for (const pattern of UPLOAD_RETURN_PATTERNS) {
    const url = trimmed.match(pattern)?.[1];
    if (url) return url;
  }
  return undefined;
};

/**
 * An extension for the uploaded file, so Roam serves it as the type it is.
 *
 * Taken from the recorded name where there is one, since that is what the publisher saw,
 * and derived from the MIME subtype otherwise. Neither is guaranteed, and an asset with
 * no extension still uploads and still renders for the types Roam sniffs.
 */
const extensionFor = ({
  sourcePath,
  mimetype,
}: {
  sourcePath?: string | null;
  mimetype?: string;
}): string => {
  const leaf = sourcePath?.split("/").pop() ?? "";
  const dot = leaf.lastIndexOf(".");
  if (dot > 0) return leaf.slice(dot);

  // `image/svg+xml` carries its useful part before the `+`; anything else non-alphanumeric
  // is not an extension we should be inventing.
  const subtype = mimetype?.split("/")[1]?.split("+")[0] ?? "";
  return /^[a-z0-9]+$/i.test(subtype) ? `.${subtype}` : "";
};

/**
 * `imported-<sha256>`, which is what makes the registry a cache rather than a source of
 * truth: the hash travels with the file, so a lost registry can be rebuilt by reading
 * the names of the files a graph already holds. See design.md Decision 4.
 */
export const mirroredAssetFileName = ({
  contentHash,
  sourcePath,
  mimetype,
}: {
  contentHash: string;
  sourcePath?: string | null;
  mimetype?: string;
}): string => `imported-${contentHash}${extensionFor({ sourcePath, mimetype })}`;

export const mirrorAssetToRoamStorage = async ({
  client,
  contentHash,
  sourcePath,
}: {
  client: DGSupabaseClient;
  contentHash: string;
  /** The name the reference records, used only to give the upload an extension. */
  sourcePath?: string | null;
}): Promise<AssetMirrorResult> => {
  const alreadyMirrored = readMirroredAssetUrl(contentHash);
  if (alreadyMirrored)
    return { status: "reused", contentHash, url: alreadyMirrored };

  const storage = client.storage.from(SHARED_ASSET_BUCKET);

  // Size is read from the object's metadata rather than from the downloaded bytes, so an
  // oversized asset costs one small request instead of the download this cap exists to
  // prevent. Where the metadata omits it, the check moves after the download.
  const { data: info, error: infoError } = await storage.info(contentHash);
  if (infoError) throw infoError;
  const tooLarge = (size: number): SkippedAsset => ({
    status: "skipped",
    contentHash,
    reason: "too-large",
    size,
    limit: MAX_IMPORTED_ASSET_BYTES,
  });
  if (
    info?.size !== undefined &&
    isAssetTooLarge({ size: info.size, limit: MAX_IMPORTED_ASSET_BYTES })
  )
    return tooLarge(info.size);

  const { data: blob, error: downloadError } = await storage.download(
    contentHash,
  );
  if (downloadError) throw downloadError;
  if (!blob)
    throw new Error(`No bytes in shared storage for asset ${contentHash}`);
  if (isAssetTooLarge({ size: blob.size, limit: MAX_IMPORTED_ASSET_BYTES }))
    return tooLarge(blob.size);

  const mimetype = info?.contentType || blob.type || undefined;
  const file = new File(
    [blob],
    mirroredAssetFileName({ contentHash, sourcePath, mimetype }),
    mimetype ? { type: mimetype } : undefined,
  );

  // Upload first, then record. A placeholder written beforehand would carry no URL, so a
  // later run could neither reuse the upload nor find it, and Roam exposes no way to list
  // a graph's files. A crash between the two leaves one orphaned file, which is the
  // residue Roam's own documentation treats as normal. See design.md Decision 5.
  const uploadReturn = await window.roamAlphaAPI.file.upload({ file });
  const url = extractUploadedUrl(uploadReturn);
  if (!url)
    throw new Error(
      `Roam returned an upload result this code cannot read a URL from: ${uploadReturn}`,
    );

  await recordMirroredAsset({ contentHash, url });
  return { status: "mirrored", contentHash, url };
};

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { DGSupabaseClient } from "@repo/database/lib/client";
import { MAX_IMPORTED_ASSET_BYTES } from "@repo/database/lib/assetLimits";
import {
  extractUploadedUrl,
  mirrorAssetToRoamStorage,
  mirroredAssetFileName,
} from "../mirrorAssetToRoamStorage";
import { readMirroredAssetUrl, recordMirroredAsset } from "../assetRegistry";

vi.mock("../assetRegistry", () => ({
  readMirroredAssetUrl: vi.fn(),
  recordMirroredAsset: vi.fn(),
}));

const HASH = "a".repeat(64);
const UPLOADED_URL =
  "https://firebasestorage.googleapis.com/v0/b/firescript-577a2.appspot.com/o/imgs%2Fapp%2FMAPLab%2FZr4mWpN70c.png?alt=media&token=9f1c07a4";

/**
 * A stand-in for the registry that behaves like graph props: what is recorded is what a
 * later read returns, so a second call for the same hash sees the first call's upload.
 */
const useInMemoryRegistry = () => {
  const entries = new Map<string, string>();
  vi.mocked(readMirroredAssetUrl).mockImplementation((hash) =>
    entries.get(hash),
  );
  vi.mocked(recordMirroredAsset).mockImplementation(async ({ contentHash, url }) => {
    entries.set(contentHash, url);
  });
  return entries;
};

const makeClient = ({
  size = 1024,
  contentType = "image/png" as string | undefined,
}: { size?: number; contentType?: string } = {}) => {
  const blob = new Blob([new Uint8Array(size)], {
    type: contentType ?? "",
  });
  const info = vi.fn().mockResolvedValue({
    data: { size, contentType },
    error: null,
  });
  const download = vi.fn().mockResolvedValue({ data: blob, error: null });
  const client = {
    storage: { from: vi.fn(() => ({ info, download })) },
  } as unknown as DGSupabaseClient;
  return { client, info, download };
};

const mockUpload = (returnValue: string) => {
  const upload = vi.fn().mockResolvedValue(returnValue);
  // @ts-expect-error - only the file API is needed here
  window.roamAlphaAPI = { file: { upload } };
  return upload;
};

beforeEach(() => {
  useInMemoryRegistry();
});

afterEach(() => {
  vi.clearAllMocks();
});

describe("extractUploadedUrl", () => {
  // `file.upload` returns a media-type-dependent block string, not a URL.
  it.each([
    ["an image", `![](${UPLOADED_URL})`],
    ["an image with alt text", `![diagram](${UPLOADED_URL})`],
    ["a pdf", `{{[[pdf]]: ${UPLOADED_URL}}}`],
    ["audio", `{{[[audio]]: ${UPLOADED_URL}}}`],
    ["video", `{{[[video]]: ${UPLOADED_URL}}}`],
    ["anything else, as a bare URL", UPLOADED_URL],
    ["a media embed written without brackets", `{{pdf: ${UPLOADED_URL}}}`],
  ])("unwraps %s", (_label, uploadReturn) => {
    expect(extractUploadedUrl(uploadReturn)).toBe(UPLOADED_URL);
  });

  it("reports a shape it cannot read rather than guessing a URL", () => {
    expect(extractUploadedUrl("{{[[roam/render]]: something}}")).toBeUndefined();
    expect(extractUploadedUrl("")).toBeUndefined();
    // A URL embedded in prose is not an upload result, so it is not taken.
    expect(extractUploadedUrl(`see ${UPLOADED_URL} for details`)).toBeUndefined();
  });
});

describe("mirroredAssetFileName", () => {
  it("carries the hash, so a lost registry can be rebuilt from the file's own name", () => {
    expect(
      mirroredAssetFileName({ contentHash: HASH, sourcePath: "diagram.png" }),
    ).toBe(`imported-${HASH}.png`);
  });

  it("falls back to the mime subtype when the recorded name has no extension", () => {
    expect(
      mirroredAssetFileName({
        contentHash: HASH,
        sourcePath: "scan",
        mimetype: "application/pdf",
      }),
    ).toBe(`imported-${HASH}.pdf`);
  });

  it("takes the extension from a recorded name that is a path", () => {
    expect(
      mirroredAssetFileName({
        contentHash: HASH,
        sourcePath: "attachments/notes/report.docx",
      }),
    ).toBe(`imported-${HASH}.docx`);
  });

  it("invents no extension when neither source has one", () => {
    expect(mirroredAssetFileName({ contentHash: HASH })).toBe(
      `imported-${HASH}`,
    );
    expect(
      mirroredAssetFileName({ contentHash: HASH, mimetype: "image/svg+xml" }),
    ).toBe(`imported-${HASH}.svg`);
  });
});

describe("mirrorAssetToRoamStorage", () => {
  it("uploads the bytes and records the URL against the hash", async () => {
    const { client } = makeClient();
    const upload = mockUpload(`![](${UPLOADED_URL})`);

    const result = await mirrorAssetToRoamStorage({
      client,
      contentHash: HASH,
      sourcePath: "diagram.png",
    });

    expect(result).toEqual({
      status: "mirrored",
      contentHash: HASH,
      url: UPLOADED_URL,
    });
    expect(upload).toHaveBeenCalledTimes(1);
    expect(upload.mock.calls[0][0].file.name).toBe(`imported-${HASH}.png`);
    expect(recordMirroredAsset).toHaveBeenCalledWith({
      contentHash: HASH,
      url: UPLOADED_URL,
    });
  });

  it("uploads once for the same hash, however many nodes reference it", async () => {
    const { client, download } = makeClient();
    const upload = mockUpload(`![](${UPLOADED_URL})`);

    const first = await mirrorAssetToRoamStorage({ client, contentHash: HASH });
    const second = await mirrorAssetToRoamStorage({ client, contentHash: HASH });

    expect(first.status).toBe("mirrored");
    expect(second).toEqual({
      status: "reused",
      contentHash: HASH,
      url: UPLOADED_URL,
    });
    expect(upload).toHaveBeenCalledTimes(1);
    // The reused branch costs no network at all, not merely no upload.
    expect(download).toHaveBeenCalledTimes(1);
  });

  it("records the URL only after the upload returns", async () => {
    const { client } = makeClient();
    const order: string[] = [];
    const upload = vi.fn().mockImplementation(async () => {
      order.push("upload");
      return `![](${UPLOADED_URL})`;
    });
    // @ts-expect-error - only the file API is needed here
    window.roamAlphaAPI = { file: { upload } };
    vi.mocked(recordMirroredAsset).mockImplementation(async () => {
      order.push("record");
    });

    await mirrorAssetToRoamStorage({ client, contentHash: HASH });

    expect(order).toEqual(["upload", "record"]);
  });

  it("skips an asset at or above the cap, reading the size before downloading it", async () => {
    const { client, download } = makeClient({ size: MAX_IMPORTED_ASSET_BYTES });
    const upload = mockUpload(`![](${UPLOADED_URL})`);

    const result = await mirrorAssetToRoamStorage({ client, contentHash: HASH });

    expect(result).toEqual({
      status: "skipped",
      contentHash: HASH,
      reason: "too-large",
      size: MAX_IMPORTED_ASSET_BYTES,
      limit: MAX_IMPORTED_ASSET_BYTES,
    });
    // The cap exists to keep these bytes off the wire, so the skip has to precede both.
    expect(download).not.toHaveBeenCalled();
    expect(upload).not.toHaveBeenCalled();
    expect(recordMirroredAsset).not.toHaveBeenCalled();
  });

  it("skips an oversized asset whose metadata omits its size", async () => {
    const { client } = makeClient({ size: MAX_IMPORTED_ASSET_BYTES + 1 });
    const upload = mockUpload(`![](${UPLOADED_URL})`);
    const storage = client.storage.from("assets");
    vi.mocked(storage.info).mockResolvedValue({
      data: { contentType: "image/png" },
      error: null,
    } as unknown as Awaited<ReturnType<typeof storage.info>>);

    const result = await mirrorAssetToRoamStorage({ client, contentHash: HASH });

    expect(result).toMatchObject({ status: "skipped", reason: "too-large" });
    expect(upload).not.toHaveBeenCalled();
  });

  it("reports an unreadable upload result rather than recording a wrong URL", async () => {
    const { client } = makeClient();
    mockUpload("{{[[roam/render]]: something}}");

    await expect(
      mirrorAssetToRoamStorage({ client, contentHash: HASH }),
    ).rejects.toThrow(/cannot read a URL from/);
    expect(recordMirroredAsset).not.toHaveBeenCalled();
  });

  it("records nothing when the bytes cannot be downloaded", async () => {
    const { client } = makeClient();
    const upload = mockUpload(`![](${UPLOADED_URL})`);
    const storage = client.storage.from("assets");
    vi.mocked(storage.download).mockResolvedValue({
      data: null,
      error: new Error("not found"),
    } as unknown as Awaited<ReturnType<typeof storage.download>>);

    await expect(
      mirrorAssetToRoamStorage({ client, contentHash: HASH }),
    ).rejects.toThrow();
    expect(upload).not.toHaveBeenCalled();
    expect(recordMirroredAsset).not.toHaveBeenCalled();
  });
});

